<?php
namespace App\Controllers\Admin;

use App\Core\Controller;use App\Core\Auth;use App\Core\Database;use App\Core\Session;use App\Core\Audit;
use App\Payments\PaymentService;

final class OnlinePaymentAdminController extends Controller
{
    public function index():void
    {
        $u=Auth::requireAdmin();Auth::enforce('view_online_payments');$q=substr(trim($_GET['q']??''),0,120);$status=trim($_GET['status']??'');$gateway=trim($_GET['gateway']??'');$from=trim($_GET['from']??'');$to=trim($_GET['to']??'');$min=$_GET['min']??'';$max=$_GET['max']??'';$where='1=1';$params=[];
        if(in_array($status,['pending','processing','successful','failed','cancelled','refunded'],true)){$where.=' AND pt.status=?';$params[]=$status;}if($gateway!==''){$where.=' AND pt.gateway=?';$params[]=$gateway;}if($q!==''){$like='%'.$q.'%';$where.=' AND (pt.public_id LIKE ? OR pt.gateway_order_id LIKE ? OR pt.gateway_payment_id LIKE ? OR pt.donor_name LIKE ? OR pt.donor_email LIKE ? OR pt.donor_phone LIKE ?)';array_push($params,$like,$like,$like,$like,$like,$like);}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where.=' AND pt.created_at>=?';$params[]=$from.' 00:00:00';}else{$from='';}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where.=' AND pt.created_at<=?';$params[]=$to.' 23:59:59';}else{$to='';}if($min!==''&&is_numeric($min)){$where.=' AND pt.amount>=?';$params[]=(float)$min;}if($max!==''&&is_numeric($max)){$where.=' AND pt.amount<=?';$params[]=(float)$max;}
        $total=(int)(Database::one('SELECT COUNT(*) c FROM payment_transactions pt WHERE '.$where,$params)['c']??0);$pagination=admin_pager($total,25);$rows=Database::all('SELECT pt.*,c.title campaign_title FROM payment_transactions pt LEFT JOIN campaigns c ON c.id=pt.campaign_id WHERE '.$where.' ORDER BY pt.id DESC LIMIT '.(int)$pagination['per_page'].' OFFSET '.(int)$pagination['offset'],$params);
        $stats=Database::one('SELECT COUNT(*) total,COALESCE(SUM(CASE WHEN status="successful" THEN amount ELSE 0 END),0) successful_amount,SUM(status="successful") successful,SUM(status IN("pending","processing")) pending,SUM(status="failed") failed,SUM(DATE(created_at)=CURDATE() AND status="successful") today_count,COALESCE(SUM(CASE WHEN DATE(created_at)=CURDATE() AND status="successful" THEN amount ELSE 0 END),0) today_amount FROM payment_transactions')?:[];
        $this->view('admin/online-payments',['user'=>$u,'transactions'=>$rows,'stats'=>$stats,'q'=>$q,'status'=>$status,'gateway'=>$gateway,'from'=>$from,'to'=>$to,'min'=>$min,'max'=>$max,'pagination'=>$pagination,'adminTitle'=>'Online Payment Transactions'],'admin');
    }
    public function details(string $id):void{$u=Auth::requireAdmin();Auth::enforce('view_online_payments');$tx=Database::one('SELECT pt.*,c.title campaign_title,d.public_id donation_public_id FROM payment_transactions pt LEFT JOIN campaigns c ON c.id=pt.campaign_id LEFT JOIN donations d ON d.id=pt.donation_id WHERE pt.id=? LIMIT 1',[(int)$id]);if(!$tx){http_response_code(404);exit('Transaction not found.');}$events=Database::all('SELECT gateway,status_code,verified,received_at FROM payment_webhook_events WHERE order_id=? ORDER BY id DESC LIMIT 20',[$tx['gateway_order_id']]);$this->view('admin/online-payment-view',['user'=>$u,'transaction'=>$tx,'events'=>$events,'adminTitle'=>'Online Payment Details'],'admin');}
    public function sync():void{$this->requirePost();$u=Auth::requireAdmin();Auth::enforce('view_online_payments');$id=(int)($_POST['id']??0);try{$r=PaymentService::sync($id);Audit::write((int)$u['id'],'PAYMENT_STATUS_SYNC','payment_transactions',$id,'Gateway status verification requested.');Session::flash('success','Gateway status verification completed: '.substr((string)($r['msg']??'Response received'),0,180));}catch(\Throwable $e){Session::flash('error',$e->getMessage());}redirect('admin/online-payments/view/'.$id);}
    public function refund():void{$this->requirePost();$u=Auth::requireAdmin();Auth::enforce('manage_payment_gateway');$id=(int)($_POST['id']??0);$description=substr(trim($_POST['description']??'Donor refund'),0,240);try{$r=PaymentService::refund($id,null,$description);Session::flash((int)($r['status']??0)===1?'success':'error',substr((string)($r['msg']??'Refund request processed.'),0,300));}catch(\Throwable $e){Session::flash('error',$e->getMessage());}redirect('admin/online-payments/view/'.$id);}
    public function export():void
    {
        $u=Auth::requireAdmin();Auth::enforce('view_online_payments');$rows=Database::all('SELECT public_id,gateway_order_id,gateway_payment_id,donor_name,donor_email,donor_phone,amount,currency,gateway,payment_method,status,receipt_number,paid_at,created_at FROM payment_transactions ORDER BY id DESC LIMIT 5000');header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="97-foundation-online-payments-'.date('Ymd-His').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Donation Reference','Gateway Order','Gateway Payment ID','Donor','Email','Phone','Amount','Currency','Gateway','Method','Status','Receipt','Paid At','Created At']);foreach($rows as $r)fputcsv($out,$r);fclose($out);exit;
    }
}
